int map_user_io_vectors(struct request_queue *q, struct request *rq,
                        struct rq_map_data *map_data,
                        const struct iov_iter *iter, gfp_t gfp_mask) {
    int ret = 0;
    size_t iov_offset = 0;

    if (!iov_iter_count(iter))
        return -EINVAL;

    if (!map_data || !map_data->pages)
        return -EINVAL;

    if (iov_iter_is_bvec(iter)) {
        struct bio *bio;
        struct bvec_iter iter_bvec = iov_iter_bvec(iter);

        while ((bio = iter_bvec_bio(iter_bvec, iter_bvec.bio))) {
            struct bio_vec *bv;
            int i;

            for (i = 0; i < iter_bvec.nr_bvecs; i++) {
                bv = &iter_bvec.bv[i];

                if (!bv->bv_page)
                    return -EINVAL;

                if (map_data->offset + iov_offset + bv->bv_len > map_data->nr_bytes)
                    return -EINVAL;

                ret = blk_rq_map_bio_vec(rq, bv, gfp_mask);
                if (ret)
                    return ret;
            }
        }
    } else {
        struct bio *bio;
        struct bio_vec *bv;

        while (iov_iter_next_bvec(iter, &bv)) {
            if (!bv->bv_page)
                return -EINVAL;

            if (map_data->offset + iov_offset + bv->bv_len > map_data->nr_bytes)
                return -EINVAL;

            bio = bio_alloc(GFP_KERNEL, 1);
            if (!bio)
                return -ENOMEM;

            bio->bi_iter.bi_sector = map_data->offset + iov_offset;
            bio_add_page(bio, bv->bv_page, bv->bv_len, bv->bv_offset);

            ret = blk_rq_append_bio(rq, bio, gfp_mask);
            if (ret) {
                bio_put(bio);
                return ret;
            }

            iov_offset += bv->bv_len;
        }
    }

    rq->cmd_flags |= REQ_USER_MAPPED;

    return ret;
}

int blk_rq_map_user(struct request_queue *q, struct request *rq,
                    struct rq_map_data *map_data,
                    const struct iov_iter *iter, gfp_t gfp_mask)
{
    struct bio *bio = NULL;
    struct bio *head = NULL;
    size_t len = iov_iter_count(iter);
    int ret = -EINVAL;
    unsigned int nr_segs;
    size_t offset;

    if (!iov_iter_count(iter))
        return 0;

    if (!bio_get_nr_vecs(map_data->bdev))
        return -EINVAL;

    nr_segs = iov_iter_npages(iter, BIO_MAX_VECS);
    if (!nr_segs)
        return -EINVAL;

    bio = bio_kmalloc(gfp_mask, nr_segs);
    if (!bio)
        return -ENOMEM;

    bio->bi_bdev = map_data->bdev;
    bio->bi_iter.bi_sector = map_data->offset;

    offset = 0;
    while (iov_iter_count(iter)) {
        struct page *page;
        size_t size;

        if (!iov_iter_get_pages(iter, &page, 1, &size, &offset))
            break;

        if (bio_add_page(bio, page, size, offset) < size) {
            ret = -ENOSPC;
            break;
        }
    }

    if (ret < 0)
        goto unmap;

    ret = 0;
    rq->cmd_type = REQ_TYPE_BLOCK_PC;
    rq->cmd_flags |= REQ_FAILFAST_TRANSPORT | REQ_FAILFAST_DRIVER |
                     REQ_FAILFAST_DEVICE;
    rq->cmd_len = 0;

    rq->__data_len = len;
    rq->bio = head;
    rq->ioprio = IOPRIO_PRIO_DATA(iov_iter_get_ioprio(iter));
    return 0;

unmap:
    while ((bio = bio_chain_pop(bio, head)))
        bio_put(bio);
    return ret;
}

int map_user_io(struct request_queue *q, struct request *rq, struct rq_map_data *map_data,
                const struct iov_iter *iter, gfp_t gfp_mask) {
    size_t len = iov_iter_count(iter);
    struct bio *bio = NULL;
    int ret = -EINVAL;
    unsigned int nr_bios = 0;
    unsigned int offset = 0;
    size_t total_len = 0;

    if (!iter->iov || !len)
        return -EINVAL;

    if (!blk_queue_mergable(q)) {
        if (len >= q->max_hw_sectors << 9)
            return -EINVAL;
    }

    while (iov_iter_count(iter)) {
        struct bio *new_bio;
        size_t bio_len = min(iov_iter_count(iter), (size_t)queue_max_segment_size(q));
        unsigned int iov_idx = 0;

        new_bio = bio_kmalloc(gfp_mask, iov_idx + 1);
        if (!new_bio)
            goto cleanup;

        bio_set_flag(new_bio, BIO_USER);
        new_bio->bi_iter.bi_sector = 0;
        new_bio->bi_bdev = NULL;

        while (iov_idx && bio_add_user_vec(new_bio, iter, iov_idx) < bio_len) {
            iov_idx--;
            bio_len = min(iov_iter_count(iter), (size_t)queue_max_segment_size(q));
        }

        if (!bio_add_user_vec(new_bio, iter, iov_idx))
            goto cleanup;

        if (!bio) {
            bio = new_bio;
        } else {
            new_bio->bi_next = bio;
            bio = new_bio;
        }

        total_len += new_bio->bi_iter.bi_size;
        nr_bios++;
    }

    if (bio == NULL)
        return -ENOMEM;

    if (unlikely(total_len != len))
        goto cleanup;

    rq->__data_len = total_len;
    rq->bio = bio;
    ret = 0;
    return ret;

cleanup:
    while (bio) {
        struct bio *next = bio->bi_next;
        bio_put(bio);
        bio = next;
    }
    return ret;
}

int map_user_io_vectors(struct request_queue *q, struct request *rq,
                        struct rq_map_data *map_data,
                        const struct iov_iter *iter, gfp_t gfp_mask) {
    int ret = 0;
    size_t nr_segs = 0;
    struct bio *bio;
    size_t offset;

    if (!iov_iter_count(iter))
        return -EINVAL;

    if (map_data->offset + iov_iter_count(iter) > map_data->size)
        return -EINVAL;

    bio = bio_kmalloc(gfp_mask, 1);
    if (!bio)
        return -EINVAL;

    offset = 0;
    while (iov_iter_count(iter)) {
        struct bio_vec bv;
        struct page *page;
        size_t len = min(iov_iter_count(iter), (size_t)PAGE_SIZE);

        if (!iov_iter_get_pages(iter, &page, 1, &len, &offset))
            break;

        bv.bv_page = page;
        bv.bv_len = len;
        bv.bv_offset = offset;

        bio_add_page(bio, page, len, offset);
        iter->iov->iov_base = (void *)((unsigned long)iter->iov->iov_base + len);
        iter->iov++;
        iter->nr_segs--;
        nr_segs++;
    }

    if (nr_segs == 0) {
        ret = -EINVAL;
        goto cleanup;
    }

    rq->cmd_flags |= REQ_TYPE_FS | REQ_MAPPED;
    rq->cmd_len = nr_segs;
    rq->__data_len = iov_iter_count(iter);
    rq->data = bio_data(bio);
    rq->bio = bio;

    return 0;

cleanup:
    bio_put(bio);
    return ret;
}

int map_user_io_vectors(struct request_queue *q, struct request *rq,
                        struct rq_map_data *map_data,
                        const struct iov_iter *iter, gfp_t gfp_mask) {
    size_t total_len = iov_iter_count(iter);
    struct bio *bio = NULL;
    struct bio *head = NULL;
    struct iovec *iov;
    ssize_t nbytes;
    int ret = 0;

    if (!iov_iter_count(iter))
        return -EINVAL;

    iov = kcalloc(iter->nr_segs, sizeof(struct iovec), gfp_mask);
    if (!iov)
        return -EINVAL;

    nbytes = iov_iter_get iov, iter->nr_segs, iov);
    if (nbytes != total_len) {
        kfree(iov);
        return -EINVAL;
    }

    for (int i = 0; i < iter->nr_segs; i++) {
        struct iovec *vec = &iov[i];
        struct bio *b;

        b = bio_alloc(GFP_NOIO, 1);
        if (!b) {
            ret = -EINVAL;
            goto cleanup;
        }

        if (bio_add_page(b, virt_to_page(vec->iov_base),
                          vec->iov_len, offset_in_page(vec->iov_base)) != vec->iov_len) {
            bio_put(b);
            ret = -EINVAL;
            goto cleanup;
        }

        if (!head)
            head = b;
        else
            bio_chain(bio, b);
        bio = b;
    }

    rq->cmd_flags |= REQ_USER_MAPPED;
    rq->bio = head;

cleanup:
    if (ret)
        bio_put(head);
    kfree(iov);
    return ret;
}
